'use strict';
// Document 01: Limited Liability Company Agreement (the Operating Agreement). v2.
const H = require('./helpers.js');
const { CO, FORMED, DEFILE, EIN, RA, ADDR, TALENT_DATE, REDEMPTION_DATE, AUTH_UNITS, RESERVE, VP, HIST, HIST_TOTAL, CONTRIB, SERVICE, APPROX_TOTAL, APPROX_EACH, FOUNDERS, BROCK, CLASS_A, CLASS_B, OUTSTANDING, CEO, money, num, fdPct, outPct, votePct, vested, nbName, listAnd, FOUNDERS_AND, JGN_AND, tbl, personSig } = H;
const scheduleF = require('./schedule_f.js');

function p(s) { return `<p>${s}</p>`; }
function keep(text) { return text.length < 420 ? ' class="keep"' : ''; }
function sec(n, title, text) { return `<p${n === '4.2' ? ' class="keep sub"' : keep(text)}>${n} ${title}. ${text}</p>`; }
function art(t) { return `<h2>${t}</h2>`; }

const JGN_AGMT_TITLE = 'JGN Media LLC Platform Contribution, Brand License, Funding and Account Transition Agreement';
const TALENT_TITLE = 'Talent, Handicapping, and Content Services Agreement';
const CONTRIB_AND = listAnd(CONTRIB.map(f => f.name));
const DO = `Members holding at least ${VP} of Disinterested Ownership`;

// Definitions are numbered automatically, in this order. R(term) returns "Section 1.N".
const TERMS = ['Act', 'Actual Closing Date', 'Affiliate', 'Agreement', 'Bad Leaver', 'Brand', 'Brand License', 'Capital Account', 'Capital Contribution', 'Cause', 'Change of Control', 'Class A Units', 'Class B Units', 'Code', 'Common Units', 'Company Account', 'Company Business', 'Company Data', 'Company IP', 'Company Opportunity', 'Confidential Information', 'Continuous Service', 'Contributing Founder', 'Disability', 'Disinterested Ownership', 'Fair Market Value', 'Founder', 'Founder Advance', 'Founder PIIA', 'Fully Diluted Percentage', 'Good Leaver', 'Good Reason', 'Intellectual Property', 'JGN', 'JGN Agreement', 'JGN Contribution', 'JGN Member Consent', 'Major Decision', 'Member', 'Official Channel', 'Official Unit Ledger', 'Original Cost', 'Percentage Interest', 'Permitted Transferee', 'Person', 'Platform', 'Premium Offering', 'Required Meeting', 'Reserved Units', 'Restricted Unit Issuance Agreement', 'Self-Sufficiency Date', 'Service Founder', 'Service Provider', 'Service Units', 'Social Accounts', 'Supermajority Approval', 'Talent Agreement', 'Tax Representative', 'Threshold Amount', 'Transfer', 'Transfer Date', 'Treasury Regulations', 'Units', 'Unreturned Capital', 'Voting Interest'];
function R(term) { const i = TERMS.indexOf(term); if (i < 0) throw new Error('unknown defined term ' + term); return 'Section 1.' + (i + 1); }

const DEFS = {
  'Act': `"Act" means the Delaware Limited Liability Company Act, 6 Del. C. Section 18-101 et seq., as amended.`,
  'Actual Closing Date': `"Actual Closing Date" means the date on which this Agreement has been signed by the Company and all five Class A Members, each Founder has satisfied the conditions in Section 3.5, the JGN Member Consent, the JGN Agreement and the Talent Amendment have been signed, and the Company has recorded each Contributing Founder's Capital Contribution under Section 3.5, on which date the initial Class A Units and the Class B Units are issued, as recorded on the signature page.`,
  'Affiliate': `"Affiliate" means, with respect to any Person, any other Person that directly or indirectly controls, is controlled by or is under common control with that Person.`,
  'Agreement': `"Agreement" means this Limited Liability Company Agreement, including all schedules, exhibits and joinders. This Agreement is also referred to in Company records as the "Operating Agreement."`,
  'Bad Leaver': `"Bad Leaver" means a Member whose Continuous Service ends for Cause or who materially breaches confidentiality, Company IP assignment, Company Opportunity, competition, non-solicitation, non-interference, account-transition, data-security or acquisition-cooperation obligations after service ends. For the Class B Member, Continuous Service ends for Cause when the Talent Agreement is terminated following a Shortfall Notice, for the Contractor's material breach, or for conduct described in Section 2.4 of the Talent Agreement.`,
  'Brand': `"Brand" means the "Nosebleed Sports" name, marks, logos and related brand assets owned by JGN and licensed to the Company under the Brand License, as defined in the JGN Agreement.`,
  'Brand License': `"Brand License" means the license of the Brand granted by JGN to the Company in the JGN Agreement.`,
  'Capital Account': `"Capital Account" means the capital account maintained for each Member under Section 10.2.`,
  'Capital Contribution': `"Capital Contribution" means cash or property expressly accepted by the Company as a capital contribution and recorded as such in the Company's books. Each Contributing Founder's share of the JGN Contribution is that Founder's Capital Contribution. Services, Founder Advances and reimbursements are not Capital Contributions unless expressly documented by a future written capital call, capital contribution agreement or loan instrument approved under this Agreement. The Service Founder and the Class B Member make no Capital Contribution for the Service Units.`,
  'Cause': `"Cause" means fraud, theft, embezzlement, material dishonesty, intentional violation of law, felony conviction or plea, willful misconduct, material breach of this Agreement (other than Section 11.5, which is covered below) or another written Company agreement, failure to assign Company IP, unauthorized disclosure or misuse of Confidential Information, IP theft, cybersecurity misconduct, credential misuse, misappropriation of a Company Account or a Social Account, harassment, discrimination, competitive misuse of Company assets, activity prohibited by Section 11.5 that continues 15 days after written notice, or repeated willful failure to perform material duties after written notice and a 15-day cure period where cure is possible.`,
  'Change of Control': `"Change of Control" means a merger, consolidation, sale of equity, sale of substantially all assets, exclusive license of material Company IP, recapitalization or similar transaction after which the Members immediately before the transaction do not control a majority of the voting power or economic value of the surviving, acquiring or successor business. An issuance of Reserved Units approved under Section 3.13 is not by itself a Change of Control.`,
  'Class A Units': `"Class A Units" means the voting, economic limited liability company interests issued to the Founders under this Agreement as restricted Units.`,
  'Class B Units': `"Class B Units" means the non-voting, economic limited liability company interests issued under Section 3.7(b) as profits interests. "Class B Member" means Brock Smith and any later holder of Class B Units admitted under this Agreement.`,
  'Code': `"Code" means the Internal Revenue Code of 1986, as amended.`,
  'Common Units': `"Common Units" means the Class A Units and the Class B Units together.`,
  'Company Account': `"Company Account" or "Company Accounts" means any account, tenant, workspace, repository, domain, registrar, cloud account, deployment platform, database, analytics account, payment or subscription platform account, banking account, email account, app-store developer account, the Company's Discord server, sports-data or odds API account, AI console, password manager, API account, vendor account, support account, messaging account or other system used for Company work, Company assets, Company Data or Company IP. The Social Accounts are not Company Accounts.`,
  'Company Business': `"Company Business" means the Company's current and reasonably anticipated business as described in Schedule F, including reasonable extensions of it.`,
  'Company Data': `"Company Data" means Company-created databases, schemas, normalization, metadata, analytics, derived insights, operational datasets, picks records and grading history, subscriber and member records of the Platform, system-generated telemetry, de-identified data and aggregated data, subject to customer contracts, privacy law, platform and data-provider terms and third-party rights.`,
  'Company IP': `"Company IP" means all Intellectual Property conceived, developed, authored, reduced to practice, improved, licensed, acquired or otherwise created by or for the Company, or by a Member, Service Provider, employee, contractor, advisor or agent in connection with the Company Business, including the source code, repositories, backends, APIs, databases, schemas, data pipelines, odds and scores adapters, picks tracking and grading logic, notification and subscription logic, Discord bots, roles and automations, prompts and automations, internal tooling, configurations, deployment pipelines, infrastructure, documentation, product designs, tests, integrations and related know-how of the Platform. Company IP does not include the Brand, the Social Accounts or JGN's retained assets under the JGN Agreement, an Excluded Project as defined in the Founder PIIA, Work Product that the Talent Agreement allocates to JGN, or work a Member does after the Member's Continuous Service ends without using Company IP or Confidential Information. Ordinary work of a business that meets the conditions of Section 11.5(ii) or (iii) is not in connection with the Company Business unless it uses Company IP or Confidential Information.`,
  'Company Opportunity': `"Company Opportunity" means a subscriber, customer, sponsorship, data-provider, sportsbook-affiliate, platform, app, community, software, partnership, referral, vendor, financing, acquisition or strategic opportunity that is within the Company Business and either known by the applicable Person to be in the Company's active pipeline, learned through Confidential Information, introduced through Company work, materially worked on by a Member for the Company, or known by the applicable Person to be actively pursued by the Company. Neither a sale of advertising or sponsorships on the Social Accounts or another media brand or creator account the Company does not own, nor ordinary work of a business that meets the conditions of Section 11.5(ii) or (iii), is a Company Opportunity unless it uses Confidential Information or is a Nosebleed Opportunity under the Talent Agreement that relates to the Platform.`,
  'Confidential Information': `"Confidential Information" means all non-public Company information, including source code, product plans, roadmaps, architecture, picks methodology and unpublished picks, subscriber and member lists and data, pricing, contracts, sponsorship and data-provider terms, financial models, credentials, acquisition discussions, tax records, banking information, data schemas, vendor terms, the terms of the Talent Agreement and the JGN Agreement, and third-party confidential information.`,
  'Continuous Service': `"Continuous Service" means service to the Company as a Founder, officer, employee, contractor, consultant, advisor or other Service Provider, as accepted by the Company; acceptance, once given, continues until Continuous Service ends as this definition provides. Continuous Service ends only when the Member resigns or dies, or when it is ended under Section 4.7 (for Cause or Disability) or, after a Change of Control, by the acquirer, the successor business or their Affiliates; removal as an officer alone does not end it. After a Change of Control, service to the acquirer, the successor business or their Affiliates counts as service to the Company. For the Class B Member, Continuous Service means performance of the Services under the Talent Agreement and ends when the Talent Agreement terminates.`,
  'Contributing Founder': `"Contributing Founder" means each of ${CONTRIB_AND}, being the four Founders who are the members of JGN and who funded the Company and the Platform through JGN.`,
  'Disability': `"Disability" means a physical or mental condition that prevents a Member from performing material service obligations for 90 consecutive days or 120 days in any 12-month period, as determined in good faith by the Company after considering reasonable accommodations required by law. Continuous Service ends by reason of Disability on the date the Company delivers to the Member, or to the Member's guardian or attorney-in-fact, through an Official Channel or another delivery method with confirmed delivery, written notice of a Disability determination approved by ${DO}, and that date is the termination date for purposes of Article 6. During a Disability, the Member's Class A Units may be voted by the Member's court-appointed guardian or by an attorney-in-fact acting under a written power of attorney.`,
  'Disinterested Ownership': `"Disinterested Ownership" means outstanding Class A Units held by Members who are not the subject of, directly conflicted in, or uniquely benefited by the matter being voted on, determined in good faith by the Members who are not the subject of the matter. A Member's ownership of JGN, disclosed in Schedule D, does not make that Member the subject of, directly conflicted in, or uniquely benefited by any matter concerning JGN, the JGN Agreement, the Brand License, a JGN Contribution or the Talent Agreement; those matters are decided by Supermajority Approval measured against all outstanding Class A Units. Any determination under this definition is made by Members holding at least ${VP} of the Class A Units held by the Members who are not the subject of the matter.`,
  'Fair Market Value': `"Fair Market Value" or "FMV" means fair market value determined in good faith under this Agreement. For the initial issuance of Units only, the Members have approved a total company equity Fair Market Value as of the Transfer Date (the "Valuation Date") equal to the aggregate JGN Contribution through that date, ${APPROX_TOTAL}, supported by the Founder Equity Fair Market Value Determination Memorandum and subject to reconsideration before the Units are issued if undisclosed Valuation Date facts exist. Because Unreturned Capital is returned first under Section 10.5, the Service Units have no liquidation value on the Valuation Date.`,
  'Founder': `"Founder" means each of the five individuals listed as Class A Members on Schedule A: the four Contributing Founders and the Service Founder.`,
  'Founder Advance': `"Founder Advance" means a documented payment, vendor charge, software expense, subscription, domain cost, hosting charge, data-provider cost, technical tool cost, professional fee or Company expense advanced by a Member personally, or by an Affiliate of a Member other than JGN, after the Actual Closing Date, and treated as a reimbursable Company obligation or separate Company operating expense rather than a Capital Contribution. Amounts funded by JGN are JGN Contributions, not Founder Advances.`,
  'Founder PIIA': `"Founder PIIA" means the Founder Proprietary Information, IP Assignment and Data Security Agreement between the Company and each Founder.`,
  'Fully Diluted Percentage': `"Fully Diluted Percentage" means, with respect to a Member, the number of Units held by that Member divided by the ${num(AUTH_UNITS)} authorized Units, expressed as a percentage, as shown on Schedule A for reference. It assumes that every Reserved Unit has been issued and is used only where this Agreement or the Talent Agreement refers to a fully diluted measure.`,
  'Good Leaver': `"Good Leaver" means a Member whose Continuous Service ends because of death, Disability, termination without Cause after a Change of Control by the acquirer, the successor business or their Affiliates, resignation for Good Reason, or another status approved by ${DO}.`,
  'Good Reason': `"Good Reason" means, without the affected Member's consent, a material reduction in title, authority or duties, a material reduction in agreed pay once pay has been formally approved, a required relocation outside a reasonable distance, or a material breach by the Company of a written agreement, after written notice and a 30-day cure period where cure is possible.`,
  'Intellectual Property': `"Intellectual Property" means all rights in inventions, works of authorship, software, source code, object code, designs, databases, data structures, trade secrets, know-how, patents, copyrights, trademarks, service marks, mask works, moral rights to the extent assignable or waivable, database rights, rights of action, proceeds, recoveries and similar rights worldwide.`,
  'JGN': `"JGN" means JGN Media LLC, a New York limited liability company and a separate legal entity owned equally, 25% each, by ${JGN_AND}.`,
  'JGN Agreement': `"JGN Agreement" means the ${JGN_AGMT_TITLE} between the Company and JGN.`,
  'JGN Contribution': `"JGN Contribution" means every amount JGN has paid or pays for Company operating expenses, Company obligations or the Company's benefit, before or after the Actual Closing Date, as recorded under the JGN Agreement, including the historical operating expenses described in Section 3.9, together with the Platform Assets JGN assigns to the Company under the JGN Agreement, to which the Members assign no value separate from the amounts JGN paid to build them. Each JGN Contribution is made by JGN on behalf of the Contributing Founders and is a Capital Contribution of the Contributing Founders, credited as Section 3.9 provides. A JGN Contribution is not a loan, bears no interest, creates no Units and no Company obligation to repay JGN or any Member, and is returned only through distributions under Section 10.5(a).`,
  'JGN Member Consent': `"JGN Member Consent" means the JGN Member Consent Approving Nosebleed Agreement, by which the members of JGN approve the JGN Agreement and the JGN Contribution and authorize JGN's signatory.`,
  'Major Decision': `"Major Decision" means a matter listed on Schedule B and any other matter expressly designated as a Major Decision in this Agreement, including under Sections 2.2 and 2.5.`,
  'Member': `"Member" means the five Founders listed as Class A Members on Schedule A, the Class B Member, and any Person later admitted as a Member under this Agreement. A Person ceases to be a Member on ceasing to hold any Units, but a former Member remains bound by Section 3.16, Article 8 and Article 11 for the periods stated there.`,
  'Official Channel': `"Official Channel" has the meaning given in Section 4.5(b).`,
  'Official Unit Ledger': `"Official Unit Ledger" means the unit ledger maintained in the Company's record book recording the holders, class, number, vesting status and repurchase of all Units and the number of Reserved Units.`,
  'Original Cost': `"Original Cost" means, for each Class A Unit held by a Contributing Founder, that Founder's Unreturned Capital divided by the number of Class A Units the Founder then holds, and, for each Service Unit, zero.`,
  'Percentage Interest': `"Percentage Interest" means, with respect to a Member, the number of Units held by that Member divided by the total number of Units then outstanding (Class A Units and Class B Units together, and excluding Reserved Units), expressed as a percentage. The initial Percentage Interests are set forth on Schedule A.`,
  'Permitted Transferee': `"Permitted Transferee" means a trust or estate-planning vehicle for the benefit of a Member or the Member's immediate family, or an entity wholly owned by a Member, in each case that signs a joinder under Section 16.2 and whose admission does not impair tax, securities, governance or acquisition readiness.`,
  'Person': `"Person" means an individual, corporation, partnership, limited liability company, trust, association, governmental authority or other entity.`,
  'Platform': `"Platform" means the Nosebleed Sports mobile and web application (including the application known as Nosebleed Live), the Nosebleed Sports website, the Nosebleed Sports Discord community and the Premium Offering, together with their backends, data pipelines and related products and services, as described in Schedule F. "Platform Assets" has the meaning given in the JGN Agreement.`,
  'Premium Offering': `"Premium Offering" means the Company's paid picks, analysis, community and subscription offering delivered through the Platform, as described in Schedule F.`,
  'Required Meeting': `"Required Meeting" has the meaning given in Section 4.5(a).`,
  'Reserved Units': `"Reserved Units" means the ${num(RESERVE)} authorized Units that are unissued on the Actual Closing Date and reserved under Section 3.13 for issuance to future strategic partners and, as Section 3.7(b) provides, for Milestone Units under the Talent Agreement, together with any Units that later become Reserved Units under Section 6.5.`,
  'Restricted Unit Issuance Agreement': `"Restricted Unit Issuance Agreement" means, for each Founder, the agreement so titled between the Company and that Founder, dated as of the Actual Closing Date, under which the Company issues to that Founder the Class A Units shown opposite that Founder's name on Schedule A.`,
  'Self-Sufficiency Date': `"Self-Sufficiency Date" has the meaning given in the JGN Agreement.`,
  'Service Founder': `"Service Founder" means ${SERVICE.name}, who receives Class A Units for services under Section 3.7(a).`,
  'Service Provider': `"Service Provider" means a Member, officer, employee, contractor, consultant, advisor or other Person providing services to the Company.`,
  'Service Units': `"Service Units" means the Class A Units issued to the Service Founder under Section 3.7(a) and the Class B Units, each issued for services as profits interests.`,
  'Social Accounts': `"Social Accounts" means the Nosebleed Sports social media accounts and the other social media accounts, channels and audiences owned by JGN, including the accounts managed by the Class B Member under the Talent Agreement, as described in the JGN Agreement. The Social Accounts are owned by JGN and are not Company assets.`,
  'Supermajority Approval': `"Supermajority Approval" means approval, by affirmative written vote counted under Section 5.3, of Members holding at least ${VP} of outstanding Class A Units, together with any affected-Member consent required by this Agreement or applicable law.`,
  'Talent Agreement': `"Talent Agreement" means the ${TALENT_TITLE} dated as of ${TALENT_DATE} among JGN, the Company and Brock Smith, as amended by the First Amendment to it signed by its three parties in connection with the Founder closing (the "Talent Amendment") and as further amended in accordance with its terms. "Contractor," "Company Party," "Initial Units," "Milestone Units," "Milestone," "Services," "Managed Accounts," "Monthly Fee," "Brand Deal Revenue," "Qualifying Revenue," "Cumulative Qualifying Revenue," "Shortfall Notice," "Work Product" and "Nosebleed Opportunity" have the meanings given there.`,
  'Tax Representative': `"Tax Representative" means the partnership representative under Code Section 6223 and the equivalent representative under any similar state or local tax law.`,
  'Threshold Amount': `"Threshold Amount" means, for Units issued after the Actual Closing Date as profits interests, including Milestone Units, the amount the Company determines in good faith to be the total equity value of the Company immediately before that issuance, recorded in the Official Unit Ledger. Those Units do not share in any distribution until distributions made after their issuance date to the Units outstanding immediately before their issuance equal the Threshold Amount. The Service Units issued on the Actual Closing Date carry no separate Threshold Amount: they share only under Section 10.5(b), after all Unreturned Capital has been returned.`,
  'Transfer': `"Transfer" means to sell, assign, pledge, hypothecate, encumber, gift, exchange, transfer or otherwise dispose of Units, voluntarily or involuntarily, directly or indirectly.`,
  'Transfer Date': `"Transfer Date" means the Actual Closing Date, being the date on which the initial Class A Units are issued to each Founder and the Class B Units are issued to the Class B Member after all closing conditions are satisfied. Issuance of Units on the Transfer Date is not a "Transfer."`,
  'Treasury Regulations': `"Treasury Regulations" means the final, temporary or proposed Treasury Regulations promulgated under the Code, as amended.`,
  'Units': `"Units" means Common Units and any other class or series of limited liability company interests approved under this Agreement.`,
  'Unreturned Capital': `"Unreturned Capital" means, for a Member, that Member's Capital Contributions less (a) the distributions the Member has received under Section 10.5(a) and (b) the Original Cost of Units repurchased from the Member under Article 6.`,
  'Voting Interest': `"Voting Interest" means, with respect to a Class A Member, the number of Class A Units held by that Member divided by the total number of Class A Units then outstanding, expressed as a percentage. The initial Voting Interests are set forth on Schedule A. Class B Units have no Voting Interest.`,
};
for (const t of TERMS) if (!DEFS[t]) throw new Error('missing definition text for ' + t);
if (Object.keys(DEFS).length !== TERMS.length) throw new Error('definition list and text do not match');

const recitals = `
<p>This Limited Liability Company Agreement (this "Agreement") is entered into as of the Actual Closing Date by and among ${CO}, a Delaware limited liability company (the "Company"), and the five individuals identified as Class A Members on Schedule A, and binds the Class B Member identified on Schedule A as Section 3.7(b) provides.</p>
<h2>RECITALS</h2>
<p>A. The Company was formed as a Delaware limited liability company on ${FORMED}.</p>
<p>B. The Company is member-managed, has no board of managers, and is organized to build and operate the Nosebleed Sports mobile and web application, website, Discord community and premium picks offering, and related sports media, data, community, subscription and technology products and services, under a license of the Nosebleed Sports brand from JGN Media LLC.</p>
<p>C. The Platform began as the idea and work of ${CEO.name}, was funded entirely by JGN Media LLC, whose four members are the Contributing Founders, and is being completed by ${SERVICE.name}. The Members intend that all Platform-specific intellectual property, data rights, Company Accounts, subscriber relationships, commercial records, documentation and acquisition-readiness records be owned or controlled by the Company; that the Nosebleed Sports brand and the Social Accounts remain owned by JGN and be licensed and made available to the Company under the JGN Agreement; and that JGN's funding of the Company be the Capital Contribution of the Contributing Founders; in each case subject to customer contracts, platform terms, applicable law and third-party rights.</p>
<p>D. The Members intend that the Company issue the Class A Units to the Contributing Founders in exchange for their Capital Contributions made through JGN, and to the Service Founder for his services, with no Founder purchasing Units for cash, and that the Company issue the Class B Units to Brock Smith on the Actual Closing Date under the Talent Agreement.</p>
`;

const art1 = art('ARTICLE 1 – DEFINITIONS') + TERMS.map((t, i) => { const text = DEFS[t]; return `<p${keep(text)}>1.${i + 1} ${text}</p>`; }).join('');

const art2 = art('ARTICLE 2 – FORMATION; PURPOSE; TERM') +
sec('2.1', 'Formation', `The Company was formed as a Delaware limited liability company under the Act by filing a certificate of formation with the Delaware Secretary of State on ${FORMED} (Delaware file number ${DEFILE}). The Company's federal employer identification number is ${EIN}.`) +
sec('2.2', 'Name', `The Company's legal name is ${CO}. Any material name change requires approval as a Major Decision and, while the Brand License is in effect, must comply with the JGN Agreement.`) +
sec('2.3', 'Offices and Registered Agent', `The Company's Delaware registered agent is ${RA}. The Company's principal business office is ${ADDR}, and may be changed by the Chief Executive Officer unless the change is material, in which case the change requires Supermajority Approval.`) +
sec('2.4', 'Purpose', `The Company may engage in any lawful business approved under this Agreement, including the Company Business.`) +
sec('2.5', 'Regulated Activities', `The Company may not accept, place, broker or facilitate wagers; operate or hold itself out as a sportsbook, betting exchange, daily-fantasy operator or prediction market; launch or materially expand any sportsbook, betting-operator or affiliate program, or any paid picks or handicapping activity, in a jurisdiction where that activity requires a gaming, sports-wagering, affiliate, vendor or tout license or registration; or launch or materially expand payment facilitation, money transmission, stored value, lending or similar regulated financial services; in each case without Major Decision approval, which approval must address the licensing, registration, advertising, age-verification, responsible-gambling and compliance requirements for the activity, including use of a licensed or regulated partner where required.`) +
sec('2.6', 'Term', `The Company continues until dissolved under Article 14 or the Act.`) +
sec('2.7', 'Strategic Acquisition Objective', `The Members acknowledge the Company's business objective of building toward a potential strategic acquisition within approximately three to seven years. This objective guides acquisition-readiness practices but does not require a sale, force a Change of Control, alter ownership, or reduce the approval thresholds in this Agreement.`) +
sec('2.8', 'Effectiveness', `This Agreement becomes effective on the Actual Closing Date, except that Sections 3.5, 3.6, 11.5, 11.6, 16.3, 16.4 and 16.6 bind the Company and each Founder from the date that Founder signs. The Actual Closing Date, the Transfer Date, the Valuation Date and the vesting commencement date under Section 6.2 are the same date unless this Agreement is amended under Article 16 to provide otherwise.`);

const art3 = art('ARTICLE 3 – MEMBERS; UNITS; CAPITAL; JGN FUNDING') +
sec('3.1', 'Authorized and Issued Units', `The Company is authorized to issue ${num(AUTH_UNITS)} Units. After completion of the Founder closing on the Actual Closing Date, the Company will have ${num(CLASS_A)} issued Class A Units, held by the five Founders listed on Schedule A, and ${num(CLASS_B)} issued Class B Units, held by the Class B Member, for ${num(OUTSTANDING)} outstanding Units in total. The remaining ${num(RESERVE)} authorized Units are Reserved Units and are unissued. The Percentage Interests on Schedule A total 100% of the outstanding Units, and the Voting Interests on Schedule A total 100% of the outstanding Class A Units.`) +
sec('3.2', 'Initial Members', `The only initial Class A Members are ${FOUNDERS_AND}. The only initial Class B Member is Brock Smith.`) +
sec('3.3', 'No Other Initial Members', `No Person other than the six individuals listed on Schedule A is a Member, equityholder, founder-equity recipient, profits-interest holder, optionholder or holder of any voting, distribution, tax-allocation, preemptive, anti-dilution, right-of-first-refusal, tag-along, drag-along or Member information right unless later admitted or issued rights under this Agreement. The only agreement made before the Actual Closing Date that promises an interest in the Company is the Talent Agreement, which Section 3.7(b) performs. JGN is not a Member. Jacob Glover, a former member of JGN whose entire interest in JGN was redeemed effective ${REDEMPTION_DATE}, confirmed in that redemption agreement that he holds no ownership interest in, and has no claim to any ownership interest in, the Company. Any other limited liability company interest in the Company existing immediately before the Actual Closing Date, including any interest of the Person who formed the Company, is cancelled and replaced by the Common Units issued on the Actual Closing Date.`) +
sec('3.4', 'Founder Capital Contributions and Fair Market Value', `The Members approve a total company equity Fair Market Value as of the Transfer Date equal to the aggregate JGN Contribution through that date, ${APPROX_TOTAL}. Each Contributing Founder makes, effective on the Actual Closing Date, a Capital Contribution to the Company through JGN equal to one quarter of that JGN Contribution, ${APPROX_EACH} each, and receives in exchange the Class A Units shown opposite that Founder's name on Schedule A, including immediately vested Units and unvested Units subject to monthly vesting. The Units a Founder receives reflect the Founder's agreed share of the Company's future profits and are not proportionate to Capital Contributions; contributed capital is returned first under Section 10.5(a) and earns no other preference.`) +
sec('3.5', 'Recording of Contributions and Issuance', `No Founder purchases Units for cash, and no payment is made into a Company account for any Unit. The Chief Executive Officer compiles the JGN Contribution through the Actual Closing Date from JGN's payment records, as set out in Schedule C and the record-book document of the same title, and makes those records available to every Member before signing. Each Contributing Founder confirms, by signing that Founder's Restricted Unit Issuance Agreement, that JGN made the payments recorded there on the Contributing Founders' behalf. The Company records each Contributing Founder's Capital Contribution in the Founder Capital Contribution Ledger and issues the Founder a receipt. No Unit issuance is effective for any Founder until that Founder executes the applicable Restricted Unit Issuance Agreement and all required Founder IP and Company agreements and, for a Contributing Founder, the Company records that Founder's Capital Contribution. On the Actual Closing Date the Company issues ${num(CLASS_A)} restricted Class A Units to the Founders and ${num(CLASS_B)} Class B Units to the Class B Member. Any amount JGN paid for the Company before the Actual Closing Date that is not in Schedule C, and that JGN documents to the Members within 60 days after the Actual Closing Date, is added to the JGN Contribution and credited in the same way.`) +
sec('3.6', 'No Notes or Purchase Price; Finality; Lapse', `No Founder gives a promissory note or owes a purchase price or deferred payment for Units. Once the Actual Closing Date occurs, a recorded Capital Contribution may not be reduced, refunded, offset or recharacterized, except as Sections 3.5 and 10.5 provide. Until then, no JGN Contribution is a Capital Contribution. If the Actual Closing Date has not occurred within 120 days after the first Founder signs this Agreement, every recorded contribution lapses, no Units are issued on it, and the amounts JGN paid are treated as if they had never been recorded; a later closing requires each contribution to be recorded again.`) +
`<p class="sub">3.7 Service Units.</p>` +
p(`(a) Service Founder. On the Actual Closing Date the Company issues ${num(SERVICE.units)} Class A Units to ${SERVICE.name} for his services to the Company: completing the build of the app, the website and the Discord community for launch, and serving as Chief Technology Officer. He pays no purchase price and makes no Capital Contribution, and his opening Capital Account is zero. His Class A Units vote, vest and are subject to repurchase like every other Founder's Class A Units under Articles 5 and 6.`) +
p(`(b) Class B Member. On the Actual Closing Date the Company issues ${num(CLASS_B)} Class B Units to Brock Smith as the Initial Units under Section 5.1 of the Talent Agreement, as amended by the Talent Amendment. The Class B Units are issued for no purchase price, the Class B Member makes no Capital Contribution for them, and they are fully vested on issuance. The Class B Member is admitted as a Member on the issuance under Section 18-301 of the Act and is bound by this Agreement through his joinder in the Talent Amendment and, as the Act provides in its definition of a limited liability company agreement, whether or not he signs this Agreement. The Company shall deliver to the Class B Member a copy of this Agreement and of the Class B Unit Issuance Record within 10 days after the Actual Closing Date. Milestone Units earned under Section 5.2 of the Talent Agreement are issued as Class B Units, with a Threshold Amount, and reduce the Reserved Units, without any further Member approval; the Members approve those issuances by signing this Agreement. Class B Units carry the economic rights stated in this Agreement, including Articles 6, 7 and 10, and no voting, consent, approval or information right other than the rights this Agreement expressly grants to the Class B Member and the rights of a member under the Act that this Agreement may not restrict; to the extent the Act permits, the Class B Member's right to information under Section 18-305 of the Act is limited to the Company's annual financial statements, the Class B Member's Schedule K-1 and the Official Unit Ledger entry for the Class B Units.`) +
p(`(c) Profits interests. The Service Units are issued as profits interests within the meaning of Revenue Procedures 93-27 and 2001-43. They share in distributions only under Section 10.5(b), after all Unreturned Capital has been returned, so that a holder of Service Units would receive nothing if the Company sold its assets for their Fair Market Value on the Valuation Date and liquidated.`) +
sec('3.8', 'Separate Founder Obligations', `Founder service duties, IP assignments, confidentiality, invention assignment, data-security obligations, restrictive covenants, acquisition cooperation and continuing Founder obligations remain separate and independently enforceable obligations. They are not Capital Contributions, reimbursement arrangements or offsets. The IP assignments do not increase Unit allocations or modify ownership percentages. Services any Founder performed for the Platform before the Actual Closing Date create no claim for compensation, reimbursement or additional Units.`) +
sec('3.9', 'JGN Contributions; Historical Operating Expenses', `Every operating expense of the Company and of the Platform through the Actual Closing Date was paid by JGN: ${APPROX_TOTAL} from May through November 2026, as listed in Schedule C and the record-book document of the same title. No Member paid any of those expenses personally, and the Service Founder and the Class B Member paid none of them. The Company never borrowed that money and owes none of it to JGN or to any Member. It is the JGN Contribution through the Actual Closing Date and is credited, one quarter each, to the Capital Accounts and the Unreturned Capital of the four Contributing Founders. Every JGN Contribution made after the Actual Closing Date under the JGN Agreement is credited equally among the Contributing Founders who are Members when it is paid, unless JGN notifies the Company in writing of a different allocation among them, and no additional Units are issued for it. No Member is required to make any further Capital Contribution, and no Member owes any amount in respect of a JGN Contribution.`) +
sec('3.10', 'Founder Advances and Reimbursable Expenses', `Founder Advances are reimbursable Company obligations or separate Company operating expenses, not Capital Contributions, and do not alter Units, Percentage Interests, voting rights, distribution rights, vesting, Capital Accounts or tax allocations unless specifically documented by a future written capital call, capital contribution agreement or loan instrument approved under this Agreement.`) +
sec('3.11', 'Approval of New Founder Advances', `Material new Founder Advances over $1,000 individually or $2,500 in the aggregate in any calendar quarter require advance Supermajority Approval unless the item is already in an approved budget. Emergency expenditures may be approved after the fact if reasonably necessary, promptly reported and properly documented. A Founder Advance permitted under this Section is a reimbursable Company obligation only if the approval states so; otherwise it creates no Company obligation and no obligation of any other Member.`) +
sec('3.12', 'Founder Equity FMV Memorandum', `The Members approve the Founder Equity Fair Market Value Determination Memorandum as a good-faith Company record supporting the total company equity Fair Market Value on the Valuation Date and the treatment of the Service Units as profits interests. The memorandum is not an independent appraisal, certified valuation, fairness opinion, formal tax opinion or approval by any tax authority. Future financing, revenue, product development, commercial success, strategic value or acquisition value does not retroactively change the good-faith Fair Market Value determined as of the Transfer Date.`) +
sec('3.13', 'Reserved Units; Strategic Partners', `The Reserved Units are reserved for issuance to future strategic partners of the Company, including sports-data, media, distribution, talent, sponsorship, technology or capital partners, and for Milestone Units under Section 3.7(b). An issuance of Reserved Units to a strategic partner requires Supermajority Approval as a Major Decision under Schedule B, a written description of the partner, the number and class of Units, the price or other consideration, any Threshold Amount, the vesting and the resulting capitalization, the partner's joinder under Section 16.2 and a Company-approved proprietary information and IP agreement, and compliance with applicable tax and securities law. Reserved Units may be issued as Class A Units, Class B Units or another class approved under this Agreement. No equity incentive pool, option pool, phantom-equity pool or similar pool exists other than the Reserved Units; any future pool, or any increase in the number of authorized Units, requires Supermajority Approval, updated Company records and any required tax, securities and service-provider documentation. Until issued, Reserved Units carry no rights, do not vote and are excluded from every threshold measured by outstanding Units.`) +
sec('3.14', 'Preemptive Rights', `If the Company proposes to issue equity securities other than Reserved Units issued under Section 3.7(b) or 3.13, it shall first offer each Class A Member the right to purchase that Member's pro rata share of the offered securities, by Voting Interest, on the same price and terms, except as waived by Supermajority Approval. Each offer stays open for 15 days after written notice of its terms; securities not taken up may then be issued to others, subject to any other approval this Agreement requires, within 60 days and on terms no better than those offered.`) +
sec('3.15', 'No Anti-Dilution', `No Member or Service Provider has price-based anti-dilution, full-ratchet protection, financing-price protection or a guaranteed permanent ownership percentage unless approved by an express amendment signed under Article 16. The percentages in the Talent Agreement are fixed as that agreement provides and are implemented through Section 3.7(b).`) +
sec('3.16', 'Member Payment Obligations; Seven-Day Settlement', `Any amount that a Member owes the Company under this Agreement or another written Company record (including a capital call approved under this Agreement that the Member has agreed to in writing, or reimbursement of a documented Company payment made on the Member's behalf) is due in full within seven calendar days after the Company delivers written notice of the amount, with reasonable supporting documentation, to the Member through an Official Channel with confirmed delivery, unless ${DO} approve a longer period or a written payment plan. No Member owes any amount in respect of a JGN Contribution. The Company may offset any amount past due under this Section 3.16 that is documented and not disputed in good faith against distributions otherwise payable to that Member under Article 10 or Article 14 and against any repurchase or call-option price otherwise payable to that Member under Article 6, until the amount is satisfied. An amount that the Member disputes in good faith by written notice through an Official Channel within the seven-day period is not in default, and is not a failure event, until the dispute is resolved by written agreement, by approval of ${DO}, or, if not so resolved within 30 days after the dispute notice, by an independent accounting firm whose written decision is final and binding and whose fees are shared equally unless the firm directs otherwise. The Member and the Company (acting through an officer other than that Member) select that firm in the manner Section 6.9 provides for a valuation firm, with the 15 days running from the end of that 30-day period; if a party selects no firm within 10 days after those 15 days, the firm selected by the other party decides; if neither party selects a firm, the amount in the notice stands; and if a third firm is required and none is selected, the two firms each decide and the average of their decisions controls. The firm or firms decide within 30 days after selection, and the Company shall engage them promptly on customary terms. Any amount determined to be owed is due within seven calendar days after the dispute is resolved. A payment default under this Section 3.16 that continues for more than 30 days after notice is a failure event for purposes of Section 4.5(e). Amounts disputed in good faith may not be offset under this Section 3.16 and may be deducted from any repurchase price only as permitted by Section 6.10. At the closing of a Change of Control, every unpaid amount under this Section 3.16 becomes due and, as each Member authorizes, is paid to the Company through the closing funds flow from the consideration payable to that Member at the closing, and any part disputed in good faith is held in escrow from that consideration until the dispute is resolved. A Member's obligations under this Section survive the end of Continuous Service and the repurchase or any sale of that Member's Units.`);

const officerRows = FOUNDERS.map(f => [nbName(f), `${f.office} ("${f.short}")`, f.lane]);
const art4 = art('ARTICLE 4 – MANAGEMENT; OFFICERS; AUTHORITY') +
sec('4.1', 'Member-Managed Company', `The Company is member-managed. There is no board of managers and no separate manager body. Company approvals are Class A Member approvals or authorized-officer actions under this Agreement.`) +
sec('4.2', 'Officers', `The Members delegate ordinary-course authority to the officers listed below, subject to budgets, approved plans, this Agreement, the JGN Agreement and Member approval rights. The Class B Member holds no office.`) +
tbl(['Officer', 'Title', 'Core ordinary-course lane'], officerRows, 'w') +
sec('4.3', 'Ordinary-Course Spending Authority', `The CEO may approve ordinary-course Company expenses up to $5,000 individually. Each other officer may approve ordinary-course expenses up to $2,000 within that officer's lane; an officer expense above $2,000 and up to $5,000 requires the CEO's approval. An expense above $5,000 and up to $25,000 requires the approval of the CEO and at least two additional Founders then in Continuous Service. Expenses above $25,000 require Supermajority Approval in every case. The thresholds in this Section are measured per vendor, engagement or related series of payments in any rolling 12-month period. An expense to be funded by JGN also requires JGN's funding approval under the JGN Agreement, which is JGN's decision and not a Member vote. Approvals by additional Founders under this Section 4.3 are officer-level authorizations given under the authority delegated in Section 4.2, not Member votes under Article 5, and do not count toward or reduce any threshold under Article 5.`) +
sec('4.4', 'No Expansion by Officer Title', `Officer titles do not expand spending, equity issuance, debt, related-party, Change of Control, IP transfer, pay, hiring or Major Decision authority beyond this Agreement.`) +
`<p class="sub">4.5 Member Meetings; Participation; Responsiveness; Non-Response.</p>` +
p(`(a) Required Meetings. The Class A Members shall hold (i) a weekly synchronization meeting and (ii) a quarterly business review (each, a "Required Meeting"), in each case on dates and at times set by the Chief Executive Officer on at least 48 hours' notice delivered through an Official Channel. The quarterly business review may be combined with the quarterly review under Section 3.2 of the Talent Agreement, and the Class B Member may attend any Required Meeting at the Chief Executive Officer's invitation. Required Meetings may be held in person or by video or telephone conference. Attendance at Required Meetings is a material duty of each Founder in Continuous Service. A Founder who cannot attend a Required Meeting shall give advance notice through an Official Channel and shall review, and acknowledge through an Official Channel, the meeting summary within two business days after it is posted. The Chief Executive Officer, or a Founder he designates, shall post a summary of each Required Meeting through an Official Channel.`) +
p(`(b) Official Channels. The Company's official communication channels are (i) the Company's Discord server, in the channels designated for the Members, and (ii) the designated all-Founder text message group, together with any additional or replacement channel designated by Supermajority Approval (each, an "Official Channel" and collectively, the "Official Channels"). A communication delivered through an Official Channel is effective notice for purposes of this Section 4.5 and, where delivery is confirmed, constitutes an approved delivery method under Section 16.5. Delivery is confirmed when the recipient replies to or otherwise acknowledges the communication, or when the communication is also sent by email to the recipient's address on record with the Company and is not returned as undeliverable. Notices to the Class B Member are delivered as the Talent Agreement provides.`) +
p(`(c) Responsiveness Standard. Each Founder in Continuous Service shall respond substantively to Company business directed to that Founder through an Official Channel within two business days after delivery, or within 24 hours where the communication is expressly marked time-sensitive.`) +
p(`(d) Non-Response to Approval Requests. If a matter requiring Member approval is submitted through an Official Channel and a Founder fails to respond within five business days, and thereafter fails to respond within five additional business days after a second written notice that identifies the matter, references this Section 4.5 and states in bold type that non-response is a failure event, then the non-response is a failure event for purposes of Section 4.5(e). A Member's silence, absence or failure to respond is never counted as a vote in favor of any matter, is never treated as consent, and never reduces the number of outstanding Class A Units against which an approval threshold is measured. A matter is approved only when the Class A Units actually voted in favor satisfy the applicable threshold under Article 5, measured against all outstanding Class A Units or, where this Agreement so provides, all Disinterested Ownership.`) +
p(`(e) Persistent Non-Compliance. If a Founder accumulates three or more failure events in any rolling 12-month period under this Section 4.5, Section 3.16 (payment default) or Section 4.6 (duty failure), and fails to cure within 15 days after written notice describing the failures with reasonable specificity (a default that cannot be undone is cured as Section 6.14 provides), the Members may determine, by approval of at least ${VP} of Disinterested Ownership, that the Founder's non-compliance constitutes repeated willful failure to perform material duties for purposes of the definition of Cause. A failure event under this Section 4.5 is a failure to comply with Section 4.5(a) or 4.5(c) that the Founder does not correct within two business days after written notice through an Official Channel (for a missed Required Meeting, by acknowledging the meeting summary), or a non-response under Section 4.5(d). Failure events arising from the same occasion, the same notice or the same underlying omission count as one failure event for this purpose, except that each further 30-day period of a continuing duty failure counts separately as Section 4.6 provides. Any such determination must be documented in writing and delivered to the affected Founder. A failure event caused by a condition that constitutes, or if continued would constitute, a Disability is not counted under this Section 4.5(e). This Section 4.5 does not apply to the Class B Member, whose performance is governed by the Talent Agreement.`) +
p(`(f) No Automatic Forfeiture. Nothing in this Section 4.5 causes automatic forfeiture, cancellation or repurchase of any vested or unvested Units. Any consequence affecting Units arises only under Article 6 and the other express provisions of this Agreement.`) +
sec('4.6', 'Member Duties and Contribution', `Each Founder in Continuous Service shall perform the duties of that Founder's officer lane described in Section 4.2, if any, and the tasks that the Founder accepts or that are reasonably assigned to the Founder through an Official Channel consistent with that lane, with reasonable diligence and in good faith, and shall devote the time and effort reasonably necessary to do so. A sustained failure to perform under this Section 4.6 that continues for more than 15 days after written notice describing the failure with reasonable specificity is a failure event for purposes of Section 4.5(e), and each further 30-day period during which the same failure continues uncured after that notice is a separate failure event, except that a failure caused by a condition that constitutes, or if continued would constitute, a Disability is not a failure event. This Section does not create an employment relationship, does not entitle any Member to compensation not otherwise approved under this Agreement, and does not cause automatic forfeiture of any Units.`) +
sec('4.7', 'Removal of Officers; Termination of Continuous Service', `The Members may remove any officer, or change any officer's title or lane, by Supermajority Approval measured against all outstanding Class A Units, including the Units of the affected Member; removal as an officer alone does not end Continuous Service (${R('Continuous Service')}), and a material reduction may be Good Reason under ${R('Good Reason')}, subject to the notice and cure period there. Before a Change of Control, neither the Company nor the Members may end a Founder's Continuous Service except (a) for Cause, including Cause established through a determination under Section 4.5(e), by approval of ${DO}, or (b) by reason of Disability, under ${R('Disability')}. Other than by reason of Disability, no Founder's Continuous Service may be ended by the Company or the Members without Cause before a Change of Control. Termination of Continuous Service ends every office the Member holds. Each removal or termination must be documented in writing and delivered to the affected Member through an Official Channel with confirmed delivery (or, for Disability, as ${R('Disability')} provides). Removal or termination does not affect the Member's Units except as provided in Article 6. The Class B Member's Continuous Service ends only as the Talent Agreement provides.`);

const art5 = art('ARTICLE 5 – VOTING; MAJOR DECISIONS') +
sec('5.1', 'Voting Rights', `Each issued Class A Unit has one vote whether vested or unvested. Unvested Class A Units vote unless and until repurchased by the Company under Article 6. Class B Units and Reserved Units do not vote and are not counted in any threshold under this Agreement.`) +
sec('5.2', 'Uniform Approval Standard', `Except where this Agreement measures a vote by Disinterested Ownership, every matter that requires Member approval under this Agreement or the Act, including every ordinary Member decision, requires Supermajority Approval: the affirmative written vote of Members holding at least ${VP} of outstanding Class A Units. Where this Agreement measures a vote by Disinterested Ownership, only Class A Units included in the Disinterested Ownership are entitled to vote on the matter, the ${VP} standard is measured against the Disinterested Ownership rather than all outstanding Class A Units, and the matter also requires the affirmative written vote of at least three Members holding Disinterested Ownership; if fewer than three Members hold Disinterested Ownership on the matter, the matter instead requires Supermajority Approval measured against all outstanding Class A Units. No matter may be approved at a threshold lower than ${VP} of the Class A Units entitled to vote on it, and no provision of this Agreement may be read to permit approval at a lower threshold.`) +
sec('5.3', 'Counting Rules', `Only Class A Units actually voted in favor, in writing or through an Official Channel with confirmed delivery, count toward any approval threshold. Abstentions, non-responses, absences and Units deemed voted under any theory do not count toward approval. Thresholds are measured against all outstanding Class A Units (or all Disinterested Ownership, where applicable), not against the Units present or voting. A Member may not split that Member's Units on a single matter. Member approvals may be given in writing at a Required Meeting, by written consent, or through an Official Channel with confirmed delivery, and the Company shall record each approval with the date, the matter and the Units voted in favor.`) +
sec('5.4', 'Major Decisions', `The matters listed on Schedule B require the approval threshold stated there. No officer may take a Major Decision by unilateral action.`) +
sec('5.5', 'Extraordinary Decisions', `A Change of Control, sale of substantially all Company assets, exclusive license or transfer of material Company IP, dissolution, any buy-sell, put or call process not expressly provided in Article 6 or Article 7, or amendment materially changing economic, voting, vesting or transfer rights requires approval by Members holding at least ${VP} of outstanding Class A Units and any affected-Member consent required by law or this Agreement.`) +
sec('5.6', 'Governance Reviews', `The Members shall conduct a formal governance review six months after the Actual Closing Date. The review shall cover ownership percentages, officer roles, governance, vesting, voting thresholds, the Reserved Units, future equity allocations, incentive plans, the JGN Agreement and other structural matters. The review does not automatically change ownership or rights; any amendment must satisfy the approval thresholds in this Agreement. When the Company's monthly recurring revenue first reaches $25,000, or when the Self-Sufficiency Date occurs, whichever is earlier, the Members may, but are not required to, conduct a further review of this Agreement, the JGN Agreement and the Company's governance with outside legal counsel. That further review is optional: not conducting it is not a breach or a failure event, gives no Member or other Person any claim, and does not affect the validity of this Agreement or any action taken under it.`);

const art6 = art('ARTICLE 6 – RESTRICTED UNITS; VESTING; REPURCHASE') +
sec('6.1', 'Restricted Units', `All Founder Class A Units listed on Schedule A are restricted Units subject to this Article 6 and the founder-specific Restricted Unit Issuance Agreements. Those separate agreements implement, but do not amend, the ownership percentages, vesting terms, repurchase rights, transfer restrictions and approval thresholds in this Agreement, except that a Restricted Unit Issuance Agreement approved under this Agreement may provide the more favorable treatment expressly contemplated by Section 6.4. The Class B Units are subject to this Article 6 as Section 6.16 provides.`) +
sec('6.2', 'Vesting Schedule', `For each Founder, 50% of the Class A Units listed opposite that Founder's name on Schedule A are vested immediately on the Transfer Date and the remaining 50% vest in 48 equal monthly installments, one on each monthly anniversary of the Transfer Date beginning with the first monthly anniversary, in each case only if the Founder is in Continuous Service on that date and subject to Sections 6.12 and 6.14. The Transfer Date is the vesting commencement date, and each monthly anniversary on which an installment is scheduled to vest is a monthly vesting date. Fractions may be rounded down monthly with the final installment adjusted so all Units are accounted for.`) +
sec('6.3', 'Economic and Voting Rights Before Vesting', `All issued Class A Units vote and receive distributions and tax allocations whether vested or unvested, subject to Section 7.5 in a Change of Control. Vesting affects only the Company's contractual repurchase right, related recordkeeping and the timing of, and entitlement to, consideration under Section 7.5.`) +
sec('6.4', 'Automatic Repurchase of Unvested Units', `If a Founder's Continuous Service terminates for any reason, the Company automatically repurchases all Class A Units that remain unvested after giving effect to any acceleration under Section 6.12, effective as of the termination date, except as the Members approve otherwise under Section 12.1 in the case of death. The repurchase price for unvested Units is the lower of Original Cost and Fair Market Value unless the Founder's Restricted Unit Issuance Agreement or applicable law provides a higher price; for the Service Founder's unvested Units, whose Original Cost is zero, the repurchase is for no consideration.`) +
sec('6.5', 'Repurchase Procedure', `Within 30 days after termination of Continuous Service (or, on a Member's death, within 30 days after the period in Section 12.1 ends without a different approval), the Company shall update the Official Unit Ledger maintained in the Company's record book to reflect the automatic repurchase and deliver written notice to the affected Member stating the number of unvested Units repurchased, the repurchase price, the calculation and the payment date, which shall be no later than 30 days after the notice. Payment may be made by check, wire or other lawful method, subject to Section 18-607 of the Act. Offset is permitted only for amounts agreed in writing, amounts past due under Section 3.16 that are documented and not disputed in good faith, or amounts finally adjudicated or finally awarded in binding arbitration as permitted by Section 6.10. The affected Member shall sign reasonably requested transfer instruments, but failure to sign does not invalidate the automatic repurchase. Repurchased Units are cancelled and become Reserved Units.`) +
sec('6.6', 'Vested Units Generally', `Vested Units are not automatically forfeited because of breach, officer removal, performance disagreement or termination. Vested Units remain subject to transfer restrictions, Company rights, restrictive covenants, Company Opportunity obligations, confidentiality, Company IP obligations and remedies in this Agreement.`) +
sec('6.7', 'Good Leaver Treatment', `If a Member is a Good Leaver, unvested Units are repurchased under Sections 6.4 and 6.5 (after any acceleration under Section 6.12), and vested Units remain outstanding unless separately purchased by written agreement with the Member or under Section 6.8 or 6.15; any purchase of a Good Leaver's vested Units must be at Fair Market Value without minority or marketability discounts.`) +
sec('6.8', 'Bad Leaver Treatment', `If a Member is a Bad Leaver, unvested Units are repurchased under Sections 6.4 and 6.5. Vested Units are not automatically cancelled. If the Bad Leaver event involves fraud, theft, IP theft, credential misuse, misappropriation of a Company Account or a Social Account, intentional destruction of Company property, intentional concealment of Company Accounts, material confidentiality breach or similar intentional misconduct and is admitted in writing, finally adjudicated or finally awarded in binding arbitration as permitted by Section 6.10, the Company may, with the approval of ${DO}, elect to purchase some or all vested Units at Fair Market Value determined under Section 6.9 without minority or marketability discounts, by written notice given within 180 days after the later of the termination date and the date the misconduct is admitted in writing, finally adjudicated or finally awarded, and shall pay the purchase price within 30 days after Fair Market Value is determined under Section 6.9. Damages finally adjudicated or finally awarded in binding arbitration may be offset only as permitted by Section 6.10.`) +
sec('6.9', 'Fair Market Value Procedure', `Except for the initial issuance approved under Section 3.4, Fair Market Value shall be determined in good faith using Company financial records, signed contracts, liabilities, restrictions in this Agreement, the terms of the Brand License, reasonable projections and comparable data if available, and the Fair Market Value of a Member's Units is the amount that Member would receive for them if the Company were sold for its total equity value and the proceeds were distributed under Section 10.5. If the Company and the affected Member disagree, they shall jointly select an independent qualified valuation firm within 15 days after either of them gives the other written notice of the disagreement. If they cannot agree, each selects one qualified firm within 10 days after that 15-day period, and those firms select a third firm within 10 days after the second of them is selected, failing which the third firm is selected by ${DO} within 10 further days, and failing that each of the two firms determines Fair Market Value and the average of the two controls; if a party selects no firm within its 10 days, the firm selected by the other party determines Fair Market Value, and if neither party selects a firm, the Company's good-faith determination stands. The Company acts under this Section through an officer other than the affected Member. The agreed, third or sole firm, or the two firms where their average controls, determines Fair Market Value within 30 days after the selection steps end, and the Company shall engage each firm promptly on customary terms. The Company and the affected Member each bear the fees of the firm that party selects and share equally the fees of any jointly selected or third firm. No minority or marketability discount may be applied in any purchase of Units under this Agreement.`) +
sec('6.10', 'Disputed Claims', `Disputed, unliquidated damages may not be permanently deducted from any repurchase price unless agreed in writing, finally adjudicated by a court of competent jurisdiction or, if the parties to the dispute agree in writing to arbitrate, finally awarded in binding arbitration. The Company may hold a reasonable escrow for genuinely disputed claims if approved by ${DO} and the escrow shall be released promptly when the claim is resolved.`) +
sec('6.11', 'Emergency Access Suspension', `The Company may narrowly suspend a Member's Company Account access if reasonably necessary to address fraud, theft, cybersecurity threat, IP theft, credential misuse, material confidentiality breach, data exfiltration or similar immediate threat. Mere performance disagreements, officer removal or ordinary governance disputes do not justify suspension of Company Account access, and no suspension under this Section suspends voting rights. Suspension of the Class B Member's access to a Social Account is governed by Section 9.4 of the Talent Agreement.`) +
sec('6.12', 'Full Acceleration if a Buyer Ends a Founder\'s Service', `If, at the closing of a Change of Control or at any time after it, a Founder's Continuous Service is terminated without Cause by the Company, the acquirer, the successor business or any of their Affiliates, or the Founder resigns for Good Reason, or the acquirer or successor business does not offer the Founder continued service from the closing in a role and on terms that would not give the Founder Good Reason, then 100% of that Founder's then-unvested Units vest immediately before the termination, resignation or closing, no Units of that Founder are repurchased under Section 6.4, and every amount held for that Founder's Units under Section 7.5 is released and paid to the Founder in full within 10 days. The same applies to a termination without Cause within 90 days before the closing of a Change of Control that is made at the request of the acquirer or in contemplation of the Change of Control. A Change of Control does not by itself accelerate vesting for a Founder whose Continuous Service continues. The definitive documents for a Change of Control may not reduce a Founder's rights under this Section without that Founder's written consent, and the Members shall not approve a Change of Control whose terms do not honor this Section.`) +
sec('6.13', 'Departure and Cause Call Option', `If a Member voluntarily resigns or otherwise voluntarily ends Continuous Service other than as a Good Leaver, or if a Member's Continuous Service is terminated for Cause (including Cause established through a determination under Section 4.5(e) and, for the Class B Member, termination of the Talent Agreement as described in ${R('Bad Leaver')}), the Company may, at its election, purchase some or all of that Member's vested Units at Fair Market Value determined under Section 6.9. Exercise of this call option in every case requires approval by ${DO}, which, for a termination for Cause, may be given in the same written determination that establishes Cause. The Company must exercise this call option by written notice within 180 days after the departure or termination date, and shall pay the purchase price within 30 days after Fair Market Value is determined under Section 6.9. This call option does not permit discounted repurchases, minority discounts, marketability discounts, forfeiture of vested Units, or offset except as expressly permitted by Sections 3.16 and 6.10.`) +
sec('6.14', 'Vesting Suspension During Uncured Default', `If a Founder is in default of a payment obligation under Section 3.16, a participation obligation under Section 4.5, a duty obligation under Section 4.6 or the restriction in Section 11.5, and the default remains uncured 15 days after written notice of the default is delivered to the Founder through an Official Channel, then the Founder's monthly vesting under Section 6.2 is suspended beginning with the first monthly vesting date that falls after that 15th day. No unvested Units vest during the suspension. The suspension ends when the Founder cures every default identified in a notice under this Section (a default that cannot be undone, such as a missed Required Meeting or a late response, is cured when the Founder gives the missed acknowledgment or response through an Official Channel), and vesting resumes with the next monthly vesting date after cure. Suspended monthly installments do not vest retroactively; instead, the Founder's 48-installment schedule is extended by one month for each suspended installment, so the Founder may still earn the full allocation of Units that were unvested on the Transfer Date through additional Continuous Service. A suspension under this Section adds no failure event of its own for purposes of Section 4.5(e): the underlying default is counted once under Section 3.16 or 4.5, or as Section 4.6 provides for a continuing duty failure, regardless of the length of the suspension. This Section affects only Units that have not yet vested; it does not forfeit, cancel or claw back vested Units, and it does not limit the Company's other rights under this Agreement. This Section does not apply to a default caused by a condition that constitutes, or if continued would constitute, a Disability.`) +
sec('6.15', 'Competition Call Option', `If a Founder who holds vested Units engages, at any time while holding them, including after the Restricted Period has ended, in activity that Section 11.5 prohibits during the Restricted Period, the Company may, with the approval of ${DO}, purchase some or all of those vested Units at Fair Market Value determined under Section 6.9, by written notice within 180 days after an officer other than that Founder learns of the activity, and shall pay the purchase price within 30 days after Fair Market Value is determined. Offset is permitted only as Sections 3.16 and 6.10 provide. For the Class B Member, a breach of Section 2.6 of the Talent Agreement while the Class B Member holds Class B Units has the same effect.`) +
sec('6.16', 'Class B Units', `The Class B Units issued on the Actual Closing Date are fully vested and are not subject to Sections 6.2, 6.4, 6.12 or 6.14. They are subject to Sections 6.6 through 6.11, 6.13 and 6.15, to Article 7 and to the other provisions of this Agreement that apply to Units generally, as Section 5.7 of the Talent Agreement contemplates. Milestone Units are earned and issued only as Sections 5.2, 5.5 and 5.9 of the Talent Agreement provide. If this Article 6 and Section 5 of the Talent Agreement conflict as to the Class B Units, Section 5 of the Talent Agreement controls as to whether and when Units are earned, and this Agreement controls as to everything else.`);

const art7 = art('ARTICLE 7 – TRANSFERS; RIGHT OF FIRST REFUSAL; TAG-ALONG; DRAG-ALONG') +
sec('7.1', 'General Transfer Restriction', `No Member may Transfer Units except as permitted by this Agreement. Any attempted Transfer in violation of this Agreement is void or may be refused recognition by the Company to the maximum extent permitted by law.`) +
sec('7.2', 'Permitted Transfers', `A Member may Transfer Units to a Permitted Transferee only with Supermajority Approval and a signed joinder under Section 16.2, and only if the Transfer complies with applicable tax and securities law and does not impair Company governance, tax status or acquisition readiness. The Class B Member may transfer the Class B Units to an entity wholly owned by him as Section 10.3 of the Talent Agreement contemplates, on the same conditions.`) +
sec('7.3', 'Right of First Refusal', `Before Transferring Units to a Person other than a Permitted Transferee, a Member shall deliver written notice to the Company and the Class A Members stating the proposed transferee, the number and class of Units, the price and the other material terms. The Company may elect, by approval of ${DO}, to purchase all or part of the offered Units on those terms by written notice within 30 days after delivery. For a gift or other Transfer without a bona fide cash price, the purchase price under this Section is Fair Market Value determined under Section 6.9, and any purchase at Fair Market Value closes within 15 days after Fair Market Value is finally determined. The Class A Members may then elect to purchase, pro rata by Voting Interest, any Units not taken by the Company, by written notice within 15 days after the Company's election period ends. Any Units not purchased may be Transferred to the proposed transferee, on terms no more favorable to the transferee than those stated in the notice, within 60 days thereafter, subject to Supermajority Approval and the transferee's joinder under Section 16.2.`) +
sec('7.4', 'Tag-Along', `If any Member proposes to sell Units to a Person other than a Permitted Transferee in a transaction that is not a Change of Control approved under Article 9, each other Member has the right, by written notice within 15 days after the Members' election period under Section 7.3 ends, to participate in that sale pro rata by Percentage Interest on the same terms, subject to securities, tax and purchaser restrictions and to the allocation of proceeds under Section 10.5.`) +
sec('7.5', 'Drag-Along', `In an approved Change of Control, all Members, including the Class B Member, shall cooperate, sign customary transaction documents, and sell or exchange Units on the approved terms, subject to indemnity limits approved as part of the Change of Control approval. The total consideration payable to the Members in a Change of Control (including amounts distributed to the Members from a sale of assets) is allocated among them in the amounts they would receive if it were distributed under Section 10.5. Unless the Change of Control approval expressly provides otherwise, consideration payable for Class A Units that are unvested at the closing of the Change of Control shall be held by the acquirer or in escrow and released to the Founder on the dates those Units would have vested under Section 6.2 while the Founder remains in Continuous Service, and Section 6.12 requires the whole held amount to be released if the Founder's service is ended as that Section describes. If the Founder's Continuous Service ends in a way that Section 6.12 does not cover, the Founder receives the Section 6.4 price for the Units that remain unvested, and the rest of the held amount for those Units is paid to the other Members who held Units immediately before the closing, in the amounts Section 10.5 would allocate to them, unless the Change of Control approval provides that it goes to the acquirer.`);

const art8 = art('ARTICLE 8 – COMPANY IP; CONFIDENTIALITY; ACCOUNTS') +
sec('8.1', 'Company IP Ownership', `All Company IP belongs to the Company. Each Founder shall execute and comply with the Founder PIIA and any additional assignment documents reasonably requested to confirm chain of title. Work Product of the Class B Member relating to the Platform and the Premium Offering belongs to the Company under Section 8.1 of the Talent Agreement.`) +
sec('8.2', 'JGN Boundary; Brand License', `Platform-specific work belongs to the Company: JGN assigns the Platform Assets, including the code, to the Company at the Actual Closing Date under the JGN Agreement. The Brand, the Social Accounts, the historical content published on them, JGN's sponsorship, advertising and affiliate relationships and revenue for the Social Accounts, and JGN's other media business assets remain JGN property. The Company uses the Brand under the Brand License, which is exclusive in the field the JGN Agreement defines, perpetual, royalty-free, and transferable to a successor in a Change of Control, and JGN promotes the Platform through the Social Accounts under the promotion covenant in the JGN Agreement. The JGN Agreement controls JGN-specific assignment, the Brand License, the promotion covenant, JGN Contributions, revenue allocation, account-transition and retained-asset matters. The Members, having received the disclosure in Schedule D, approve the JGN Agreement, as approved on JGN's side by the JGN Member Consent, as a Major Decision under Schedule B. The Service Founder and the Class B Member have no interest in JGN and no right to participate in JGN's own decisions.`) +
sec('8.3', 'Company Accounts', `Company-critical accounts, including source-code repositories, hosting and deployment platforms, databases and authentication services, email and transactional messaging services, analytics and error-monitoring services, the Company's Discord server and its bots and role integrations, subscription and payment platforms for the Premium Offering, app-store developer accounts, sports-data and odds API accounts, AI tool accounts used for the Platform, the password manager and the Company's bank accounts, shall be held in the Company's name or under Company-controlled administration as commercially practical, and in any event before the closing of any Change of Control, as the Company Account Schedule and Schedule D provide. The Company's bank accounts are held in the Company's legal name. Credentials and API keys are never recorded in this Agreement or the record book, and no credential or API key may be rotated, cancelled or regenerated except as the Chief Technology Officer approves.`) +
sec('8.4', 'Data, Picks and AI Restrictions', `Members may not use Confidential Information, Company Data, subscriber records, unpublished picks or picks methodology, source code, prompts, payment information, security materials or acquisition-sensitive materials to train, fine-tune, evaluate or improve third-party AI models or external analytics systems, or to operate any picks, content or community product outside the Company, without Company approval. Members shall comply with the terms of every sports-data, odds and content provider the Platform uses. This Section does not reach an Excluded Project, as defined in the Founder PIIA, other property of a Member, or JGN's retained assets.`);

const art9 = art('ARTICLE 9 – CHANGE OF CONTROL; ACQUISITION READINESS') +
sec('9.1', 'Acquisition Cooperation', `Each Member shall reasonably cooperate with acquisition diligence, buyer questionnaires, source-code review, IP confirmation, Brand License confirmation, security review, privacy review, account transfer, disclosure schedules, tax records, subscriber and data-provider consents, vendor consents and closing steps. The Company shall obtain from JGN the confirmations the JGN Agreement requires in a Change of Control.`) +
sec('9.2', 'Approval', `A Change of Control requires approval by Members holding at least ${VP} of outstanding Class A Units together with any affected-Member consent required by law or this Agreement. The proceeds of a Change of Control are allocated among the Members under Section 10.5, so that Unreturned Capital is returned first, and Section 6.12 applies to every Founder.`);

const art10 = art('ARTICLE 10 – ALLOCATIONS; DISTRIBUTIONS; TAX') +
sec('10.1', 'Tax Classification', `The Company is expected to be treated as a partnership for U.S. federal income tax purposes unless the Members approve a different classification under this Agreement.`) +
sec('10.2', 'Capital Accounts', `Capital Accounts shall be maintained in accordance with Code Section 704(b), the Treasury Regulations and the Company's books. Each Contributing Founder's Capital Account is credited with that Founder's Capital Contributions, being one quarter of the JGN Contribution through the Actual Closing Date, ${APPROX_EACH} each and ${APPROX_TOTAL} in aggregate, and with that Founder's share of each later JGN Contribution under Section 3.9. The opening Capital Accounts of the Service Founder and the Class B Member are zero.`) +
sec('10.3', 'Allocations', `Income, gain, loss, deduction and credit for each period shall be allocated among the Members so that, as nearly as possible, each Member's Capital Account at the end of the period equals the amount that Member would receive if the Company sold its assets for their book value, paid its liabilities and distributed the remainder under Section 10.5, subject to the allocations the Code and the Treasury Regulations require. Losses funded by Capital Contributions are accordingly allocated to the Members who made them.`) +
sec('10.4', 'Reserves', `The Company shall maintain commercially reasonable reserves for taxes, liabilities, working capital, approved budgets, product development, data-provider and platform fees, professional fees and acquisition-readiness costs before making distributions.`) +
sec('10.5', 'Distributions', `Distributions shall be made with Supermajority Approval and only after the reserves described in Section 10.4, in the following order: (a) first, to the Members in proportion to their Unreturned Capital, until the Unreturned Capital of every Member is zero; and (b) then, to all Members pro rata by Percentage Interests, subject to any Threshold Amount that applies to Units issued after the Actual Closing Date. Capital returned under clause (a) bears no interest and no preferred return. This Section governs every distribution, including a distribution on dissolution and the allocation of proceeds in a Change of Control.`) +
sec('10.6', 'Tax Distributions', `To the extent the Company has available cash and Members approve distributions, the Company may make tax distributions sufficient to help Members pay taxes attributable to allocated Company income, but this Agreement does not guarantee tax distributions. A tax distribution is an advance against the next amounts distributable to that Member under Section 10.5.`) +
sec('10.7', 'Profits-Interest Treatment', `The Company, the Service Founder and the Class B Member shall treat the Service Units as profits interests and their holder as the owner of them for all federal and state income tax purposes from their issuance, whether or not vested, as Revenue Procedure 2001-43 and Section 5.8 of the Talent Agreement provide, and neither the Company nor any Member shall claim a deduction for the issuance or vesting of the Service Units. The Company provides no tax advice to any Member.`) +
sec('10.8', 'Tax Representative', `${CEO.name} is appointed as the initial Tax Representative unless changed under this Agreement. A Tax Representative whose Continuous Service ends, or who is removed as an officer under Section 4.7, ceases to serve automatically, a successor is designated by ${DO}, and the Company shall file any designation change the Code requires.`);

const art11 = art('ARTICLE 11 – COMPETITION; OPPORTUNITIES; RESTRICTIVE COVENANTS') +
sec('11.1', 'Company Opportunities', `Members must present Company Opportunities first to the Company. A Member may pursue a Company Opportunity outside the Company only if the Company declines the opportunity in writing after approval by ${DO}. The Class B Member's referral obligation is governed by Section 4.3 of the Talent Agreement.`) +
sec('11.2', 'No Circumvention', `Members may not divert, conceal, side-deal, route around the Company or personally exploit Company Opportunities, Platform subscriber relationships, Platform sponsorship or data-provider opportunities, sportsbook or affiliate opportunities offered to the Platform, acquisition opportunities or strategic integrations.`) +
sec('11.3', 'Non-Solicitation', `During Continuous Service and for 12 months after service ends, a Member may not solicit Company employees, contractors, advisors, consultants or talent (including the Class B Member) with whom the Member had material Company contact to leave or reduce service to the Company, except through general solicitations not targeted at Company personnel. This Section does not restrict JGN or its members from engaging the Class B Member for JGN's retained media business as the Talent Agreement contemplates.`) +
sec('11.4', 'Non-Interference', `During Continuous Service and for 12 months after service ends, a Member may not knowingly interfere with Company subscribers, members of the Platform's community, prospects, sponsors, data providers, platform partners, strategic partners or acquisition prospects with whom the Member had material Company contact or about whom the Member learned Confidential Information.`) +
sec('11.5', 'Competition Restriction', `During the Restricted Period, a Founder may not, directly or indirectly, including through an Affiliate or another Person acting on the Founder's behalf, and whether as an owner, officer, employee, contractor, consultant, advisor, lender or investor, build, operate, control, participate in or provide services to a Competing Business in the United States or in any other country where the Company had subscribers while the Founder was in Continuous Service. A "Competing Business" means a product or service other than the Company's, whether a separate product or a distinct module of a larger one, whose primary purpose, alone or together, is (a) selling or delivering sports betting picks, predictions, player props, parlays, handicapping analysis or similar wagering recommendations to consumers on a paid, subscription or membership basis, through an app, a website, a community platform such as Discord or Telegram, a newsletter or a similar channel; (b) operating a sports fan or sports betting app, website or community whose primary monetization is a paid picks, handicapping or betting-content offering; or (c) providing to those same users an additional product of the same kind as one the Members have approved by Supermajority Approval as a Company product and recorded in Schedule F, before the Founder's Continuous Service ends and before any Change of Control. Where a larger business offers such a product, only the part of that business that builds, runs or sells it is the Competing Business, and a Founder who works for that business with no role in that part is not restricted; an ownership interest in that business is governed by exception (i). General-purpose software, sports-data feeds, sportsbooks and betting operators themselves, media brands, and content that is free to the consumer are not Competing Businesses. An approval under (c) needs no consent under Section 16.1, may not be aimed at a particular Founder's activity, and is severable from the rest of this Section. It does not restrict an activity the Founder began before receiving written notice of the approval through an Official Channel, if the Founder discloses that activity within 30 days after the notice, and Sections 11.1 and 11.2 do not apply to that activity unless Confidential Information is misused. A Founder's "Restricted Period" begins when the Founder signs this Agreement and ends 12 months after the Founder's Continuous Service ends. If on the day Continuous Service ends the Founder owes an amount under Section 3.16 for which notice has been given and that is not disputed in good faith, it instead ends 12 months after the Founder pays that amount, but never later than 24 months after Continuous Service ends. It ends earlier on the Founder's death, the dissolution of the Company, or 120 days after the first Founder signs this Agreement if the Actual Closing Date has not occurred by then (and it begins again if the Actual Closing Date later occurs), and the definitive documents for a Change of Control may replace it on terms no longer or broader than this Section unless the Founder agrees otherwise. This Section does not restrict (i) holding up to 2% of a publicly traded company, investing through a diversified fund without control over its investments, holding a passive minority interest held on the date the Founder signs this Agreement and disclosed in writing to the Company, or holding another interest approved by ${DO}; (ii) owning or operating a media brand, social accounts, a content business, a newsletter, a podcast or a creator business, a Founder's own presence as a creator or commentator, or JGN's retained media business, including the Brand, the Social Accounts, the sale of advertising and sponsorships on them, and free sports content, picks commentary and betting discussion published on them; or (iii) owning, operating or working for a software, technology, talent-management, creator-services or agency business, or any other business; so long as, under (ii) and (iii), the activity is not itself a Competing Business and does not help build, run or scale one. Selling advertising or sponsorships on a media brand or creator account at arm's length, using a generally available product as an ordinary customer, and selling a generally available product on standard terms are not participation, services or help for this purpose. None of these exceptions permits misuse of Confidential Information, diversion of Company Opportunities or a violation of fiduciary duties. The Class B Member is bound by Section 2.6 of the Talent Agreement and not by this Section 11.5.`) +
sec('11.6', 'Enforcement', `Sections 11.1 and 11.2 apply to a Founder during that Founder's Restricted Period. Activity that ${R('Company Opportunity')} excludes from Company Opportunity does not breach Section 11.2 or 11.4 unless Confidential Information is misused. The restrictions in this Article apply only to the maximum extent permitted by mandatory law, and protect Company Confidential Information, Company IP, Company goodwill, Company relationships and Company Opportunity rights. Each Founder acknowledges that the Company offers or is actively developing each kind of product listed in Section 11.5, and agrees that the Founder's ownership in the Company and access to Confidential Information support these restrictions, that they are reasonable in scope and duration, that a breach would cause irreparable harm for which the Company may seek injunctive relief under Section 16.4, and that a court may narrow any restriction it finds too broad and enforce it as narrowed. ${DO} may authorize the Company, acting through an officer other than the affected Founder, to enforce this Article against a Founder. The Company may assign its rights under this Article to a successor to the Company Business.`);

const art12 = art('ARTICLE 12 – DEATH; DISABILITY; DEPARTURE') +
sec('12.1', 'Death of a Member', `Upon a Member's death, the deceased Member's vested Units remain economic interests (and, for Class A Units, voting interests) held by the estate or lawful successor, which is admitted as a Member with respect to those Units upon signing a joinder under Section 16.2, subject to this Agreement (pending the joinder, Class A Units may be voted by the deceased Member's personal representative), and unvested Units are repurchased under Article 6 unless, within 30 days after the date of death, the Members, with Supermajority Approval, approve otherwise, in which case the approved treatment applies as of the date of death.`) +
sec('12.2', 'Disability', `Disability treatment follows Good Leaver treatment unless a Restricted Unit Issuance Agreement approved under this Agreement provides the more favorable treatment Section 6.1 permits.`) +
sec('12.3', 'No Informal Forfeiture', `No Member forfeits vested Units because of officer removal, performance disagreement or ordinary governance dispute except through an express Company right in this Agreement.`);

const art13 = art('ARTICLE 13 – FUTURE FINANCING; INCENTIVES; NO INFORMAL EQUITY') +
sec('13.1', 'Future Financing', `Future financing, investor governance documents, conversion to a corporation and the creation of investor rights each require the approval thresholds in this Agreement, must preserve Founder rights, and may amend those rights only through documents approved under this Agreement. A conversion to a corporation shall preserve the economic rights of every class of Units, the return of Unreturned Capital and the Brand License.`) +
sec('13.2', 'Future Incentives', `Any future equity incentive pool, profits-interest pool, option pool, phantom-equity plan, bonus plan, commission structure or equity-linked arrangement, other than the Reserved Units and the Milestone Units under the Talent Agreement, must receive the approvals this Agreement requires for the economics and rights granted.`) +
sec('13.3', 'No Informal Equity', `No title, contribution, content creation, audience, referral relationship, partnership discussion, product role, technical role, data role, operational assistance or funding by JGN or any other Person creates equity, Units, voting rights, distributions, tax allocations, bonus rights or other economic rights unless expressly approved in a separate written Company agreement. The only such agreement in effect on the Actual Closing Date is the Talent Agreement, performed through Section 3.7(b).`);

const art14 = art('ARTICLE 14 – DISSOLUTION; WINDING UP') +
sec('14.1', 'Dissolution Events', `The Company dissolves only upon approval by Members holding at least ${VP} of outstanding Class A Units, the entry of a decree of judicial dissolution, or another non-waivable event requiring dissolution under the Act.`) +
sec('14.2', 'Winding Up', `Upon dissolution, the Company shall wind up by collecting assets, preserving or selling Company IP (subject to the JGN Agreement as to the Brand and the Brand License), satisfying liabilities, establishing reasonable reserves, paying Founder Advances only to the extent a reimbursement obligation was approved under Section 3.11 or Schedule B, or was otherwise approved and booked as a Company obligation under this Agreement, before dissolution, and distributing remaining assets under Section 10.5.`) +
sec('14.3', 'No Informal Dissolution', `Member disputes, officer removal, deadlock, the end of JGN's funding commitment or departure of any Member do not by themselves dissolve the Company.`);

const art15 = art('ARTICLE 15 – LIABILITY; INDEMNIFICATION; DUTIES') +
sec('15.1', 'Limited Liability', `No Member is personally liable for Company debts solely by reason of being a Member, except as required by law or an express written obligation. No Member is liable to JGN, the Company or any other Member for any JGN Contribution.`) +
sec('15.2', 'Duties', `Members and officers shall act in good faith and in a manner reasonably believed to be in the Company's best interests when acting for the Company. This Agreement does not authorize fraud, bad-faith conduct, willful misconduct or knowing violation of law. A Founder who is a member of JGN does not breach a duty to the Company by owning JGN, by acting for JGN in a matter governed by the JGN Agreement, or by voting as a Member on a matter concerning JGN, provided the Founder's interest in JGN is disclosed as Schedule D provides.`) +
sec('15.3', 'Indemnification', `The Company may indemnify Members, officers and authorized agents to the fullest extent permitted by the Act for actions taken in good faith within Company authority, except for fraud, bad faith, willful misconduct, knowing violation of law or personal benefit not approved under this Agreement.`);

const art16 = art('ARTICLE 16 – AMENDMENTS; JOINDERS; MISCELLANEOUS') +
sec('16.1', 'Amendments', `Amendments require Supermajority Approval measured against all outstanding Class A Units, together with any affected-Member consent required for the affected provision. Amendments materially and adversely affecting a Member differently from similarly situated Members, including an amendment that reduces the economic rights of the Class B Units relative to the Class A Units, reduces a Member's Unreturned Capital or its priority, or reduces a Founder's rights under Section 6.12, require that Member's written consent. An amendment is effective when set out in a written instrument signed by the Company, by Members holding Units sufficient for the required Supermajority Approval, and by each Member whose consent is required.`) +
sec('16.2', 'Joinders', `Any Person admitted as a Member or receiving Units, other than the Class B Member under Section 3.7(b), must sign a joinder substantially in the form of Schedule E, a Company-approved proprietary information and IP agreement, and any equity documents required by the Company before admission or issuance is effective.`) +
sec('16.3', 'Governing Law', `Delaware law governs this Agreement, subject to mandatory law that cannot be waived.`) +
sec('16.4', 'Forum', `To the maximum extent enforceable, internal Company disputes shall be brought in state or federal courts located in Delaware. The Company may seek injunctive relief in any court with jurisdiction over the defendant or relevant property.`) +
sec('16.5', 'Notices', `Notices must be in writing and delivered by personal delivery, reputable courier, certified mail, electronic mail with confirmation, or another method approved by Supermajority Approval, including confirmed delivery through an Official Channel under Section 4.5(b). Notices are effective upon delivery or confirmed transmission.`) +
sec('16.6', 'Severability and Reformation', `Invalid or unenforceable provisions shall be enforced to the maximum lawful extent and reformed to achieve the closest lawful economic and business purpose.`) +
sec('16.7', 'Entire Agreement', `This Agreement is the Company's first written limited liability company agreement and supersedes all prior discussions, negotiations and understandings on its subject matter. The Talent Agreement, the JGN Agreement, the Founder PIIA, the Restricted Unit Issuance Agreements and other separate signed IP, service, equity, contractor and incentive agreements remain effective according to their terms if not inconsistent with this Agreement; as between this Agreement and the Talent Agreement, Section 6.16 states which controls.`) +
sec('16.8', 'Counterparts; Electronic Signatures', `This Agreement may be executed in counterparts and by electronic signature.`) +
sec('16.9', 'Independent Advice', `Each Member acknowledges having had the opportunity to seek independent legal and tax advice before signing this Agreement and that the Company has provided no legal or tax advice to any Member.`);

// Schedule A
const schedA = `<h2>SCHEDULE A – MEMBERS; UNITS; CONSIDERATION; VESTING; OFFICES</h2>` +
tbl(['Member', 'Class and office', 'Units', 'Percentage Interest (of ' + num(OUTSTANDING) + ' outstanding)', 'Voting Interest (of ' + num(CLASS_A) + ' Class A)', 'Fully Diluted Percentage (of ' + num(AUTH_UNITS) + ' authorized)'],
  FOUNDERS.map(f => [nbName(f), 'Class A; ' + f.office, num(f.units), outPct(f.units), votePct(f.units), fdPct(f.units)])
  .concat([[nbName(BROCK), 'Class B; Co-Founder; no office', num(BROCK.units), outPct(BROCK.units), 'None', fdPct(BROCK.units)],
           ['Reserved Units', 'Unissued; Section 3.13', num(RESERVE), 'Not outstanding', 'Not outstanding', fdPct(RESERVE)],
           ['<strong>Total</strong>', '', '<strong>' + num(AUTH_UNITS) + '</strong>', '<strong>100%</strong>', '<strong>100%</strong>', '<strong>100%</strong>']]), 'cap', H.CAP_COLS) +
tbl(['Member', 'Consideration for Units', 'Capital Contribution', 'Immediately vested', 'Restricted over 48 months'],
  FOUNDERS.map(f => [nbName(f), f.jgn ? 'Capital Contribution made through JGN' : 'Services; profits interest', f.jgn ? APPROX_EACH : 'None', num(vested(f)), num(vested(f))])
  .concat([[nbName(BROCK), 'Services under the Talent Agreement; profits interest', 'None', num(BROCK.units), 'None'],
           ['<strong>Total</strong>', '', '<strong>' + APPROX_TOTAL + '</strong>', '<strong>' + num(CLASS_A / 2 + CLASS_B) + '</strong>', '<strong>' + num(CLASS_A / 2) + '</strong>']]), 'cap', H.CAP_COLS) +
`<p class="note">Percentage Interests and Voting Interests are shown to three decimal places and sum to 100% of the outstanding Units and of the outstanding Class A Units respectively. All issued Class A Units vote and receive distributions and tax allocations whether vested or unvested, subject to Section 7.5 in a Change of Control. Vesting affects only the Company's contractual repurchase right, related recordkeeping and the timing of, and entitlement to, consideration under Section 7.5. Class B Units do not vote. Every distribution first returns Unreturned Capital to the Contributing Founders and is then shared by all Units pro rata (Section 10.5). The Members listed above are the only initial Members.</p>`;

// Schedule B
const T = `${VP} of outstanding Class A Units`;
const schedB = `<h2>SCHEDULE B – MAJOR DECISIONS</h2>` +
tbl(['Matter', 'Approval threshold', 'Procedure'], [
  ['Material change of Company name (Section 2.2)', T, 'Written notice of the new name and the reason for the change, and confirmation of compliance with the JGN Agreement.'],
  ['Launch or material expansion of a regulated wagering, affiliate, tout or financial activity (Section 2.5)', T, 'Written licensing, registration, advertising, age-verification, responsible-gambling and compliance plan, including any licensed or regulated partner.'],
  ['Equity issuance or new Member admission, including any issuance of Reserved Units to a strategic partner under Section 3.13 (other than Milestone Units under Section 3.7(b) and admission of a deceased Member\'s estate or successor under Section 12.1)', T, 'Written notice describing securities, economics, recipient, dilution, vesting and updated cap table, and the recipient\'s joinder.'],
  ['Creation or increase of any equity incentive pool, or any increase in authorized Units', T, 'Written plan terms, eligible recipients, pool size, dilution, vesting, tax treatment and updated cap table.'],
  ['Expenditure above $25,000, or any expenditure not approved in accordance with Section 4.3', T, 'Written description of amount, vendor, purpose, budget status, funding source, payment timing and operational need.'],
  ['Change of Control, sale of substantially all assets, merger or conversion', T, 'Written transaction summary, principal terms, consideration and its allocation under Section 10.5, buyer, treatment of the Brand License, compliance with Section 6.12, expected closing and drag procedures.'],
  ['Exclusive license or transfer of material Company IP', T, 'Written description of IP, term, field, territory, consideration and effect on Company Business.'],
  ['Debt outside approved budget', T, 'Written principal amount, lender, rate, maturity, collateral and use of proceeds.'],
  ['Material Founder Advance outside threshold', T, 'Advance approval unless emergency treatment under Section 3.11 applies.'],
  ['Amendment, waiver, termination or renewal of the JGN Agreement, the Brand License or the Talent Agreement, or any other JGN or related-party agreement', T + ', after written disclosure by each interested Member of that Member\'s interest', 'Disclosure of parties, economics, IP, Brand and account impact and conflicts.'],
  ['Dissolution, bankruptcy, or any buy-sell, put or call process not expressly provided in Article 6 or Article 7', T, 'Written terms and affected-Member rights.'],
  ['Amendment changing economic, voting, vesting or transfer rights', T + ' and affected-Member consent where required', 'Written amendment and updated schedules.'],
]);

// Schedule C
const schedC = `<h2>SCHEDULE C – HISTORICAL COMPANY OPERATING EXPENSE AND JGN CONTRIBUTION SCHEDULE</h2>` +
`<p class="keep sub">Every operating expense of the Company and of the Platform through the Actual Closing Date was paid by JGN. The amounts below are approximate and were compiled by the Chief Executive Officer from JGN's payment records, which control. Together they are the JGN Contribution through the Actual Closing Date and the Capital Contributions of the four Contributing Founders.</p>` +
tbl(['Expense', 'How the amount is calculated', 'Approximate amount', 'Paid by'], HIST.map(h => [h.cat + ': ' + h.what, h.math, money(h.amount), 'JGN'])
  .concat([['<strong>Total</strong>', HIST.map(h => money(h.amount)).join(' + '), '<strong>' + money(HIST_TOTAL) + '</strong>', 'JGN']]), 'schedc') +
tbl(['Contributing Founder', 'Share of the JGN Contribution', 'Capital Contribution and opening Unreturned Capital'], CONTRIB.map(f => [nbName(f), '25%', APPROX_EACH]).concat([['<strong>Total</strong>', '<strong>100%</strong>', '<strong>' + APPROX_TOTAL + '</strong>']])) +
`<p>${money(HIST_TOTAL)} divided by four is ${money(H.CONTRIB_EACH)}. The Service Founder and the Class B Member paid none of these expenses and have opening Capital Accounts of zero. No Member owes any reimbursement, share or other amount in respect of these expenses, and the Company owes none of them to JGN. Amounts JGN paid before the Company's formation on ${FORMED} were paid for the Platform and for the Company's benefit and are included. Amounts added under Section 3.5 are credited in the same proportions.</p>`;

// Schedule D
const schedD = `<h2>SCHEDULE D – JGN DISCLOSURE AND COMPANY ACCOUNT TRANSITION</h2>` +
`<p>JGN Media LLC is a New York limited liability company owned equally, 25% each, by ${JGN_AND}. Until ${REDEMPTION_DATE} JGN had a fifth member, Jacob Glover; JGN redeemed his entire interest under a Membership Interest Redemption and Release Agreement effective that date, in which he confirmed that he holds no ownership interest in, and has no claim to any ownership interest in, the Company. JGN's obligations under that agreement are JGN's alone. ${SERVICE.name} and the Class B Member hold no interest in JGN.</p>
<p>JGN owns the Brand and the Social Accounts, receives all revenue of the Social Accounts, and has paid every Company operating expense to date. Before the Actual Closing Date JGN also owned the Platform's code, which began as the work of ${CEO.name} and was funded by JGN. Under the JGN Agreement JGN assigns the Platform Assets, including the code, to the Company at the Actual Closing Date; licenses the Brand to the Company; promotes the Platform through the Social Accounts; and continues to fund the Company until the Self-Sufficiency Date. JGN retains the Brand, the Social Accounts and its other media business assets. Individual Member signatures do not themselves transfer assets legally owned by JGN; those assets are assigned or licensed under the JGN Agreement, executed by JGN at the entity level.</p>
<p>The categories of Company Accounts to be transitioned, and the control standard that applies to them, are recorded in the Company Account Schedule maintained in the Company's record book. On the Actual Closing Date each of these accounts is held by JGN or by a Founder for JGN. The Company shall track each Company Account's current controller and transition status in its records and keep the Company Account Schedule updated under this Schedule D. For every Company Account in the categories below, the transition standard is: transfer or provide Company control, preserve logs and history where available, and document any exception. Credentials and API keys are changed only as the Chief Technology Officer approves and are never recorded in the record book.</p>` +
`<ul class="tight">
<li>Source-code repositories for the app, the website, the Discord bots and the data pipelines</li>
<li>Hosting, storage and deployment platforms and production infrastructure</li>
<li>Databases, authentication and user-management services</li>
<li>Transactional email and messaging services</li>
<li>Analytics, error-monitoring and logging services</li>
<li>The Company's Discord server, including ownership, administrator roles, bots and role integrations</li>
<li>Subscription, payment and payout platforms for the Premium Offering</li>
<li>App-store developer accounts</li>
<li>Sports-data and odds-data API accounts (account names and owners only)</li>
<li>AI tool and developer tool accounts used for the Platform</li>
<li>Password manager</li>
<li>Google Workspace, email and shared drives used for Company work</li>
<li>The Company's bank account opened under the Banking Resolution and other finance systems</li>
</ul>` +
`<p>The Social Accounts and their handles, including the Nosebleed Sports TikTok and Instagram accounts managed by the Class B Member and the other accounts of JGN's media network, and the domains that carry the Brand, are JGN property, are not Company Accounts and are not transferred; the Company uses those domains for the Platform under the Brand License.</p>`;

// Schedule E
const schedE = `<div class="keepblock"><h2>SCHEDULE E – FORM OF MEMBER JOINDER</h2>` +
`<p>The undersigned joins this Agreement as a Member, agrees to be bound by all Member obligations, confirms receipt of the current Operating Agreement, signs all required Company IP and equity documents, and authorizes the Company to update Schedule A and the Official Unit Ledger.</p>` +
`<div class="sig"><p class="who">New Member (completed only on a later admission)</p><p>Signature: ____________________________________</p><p>Name: ________________________________________</p><p>Title/Capacity: ______________________________</p><p>Date signed: __________________________________</p></div></div>`;

// Signature page
const sigPage = `<div class="sigpage"><h2>SIGNATURE PAGE</h2>
<p><strong>Actual Closing Date (${R('Actual Closing Date')}): ________________________________</strong></p>
<div class="sig"><p class="who">Company</p><p>${CO}</p><p>By: _________________________________________</p><p>Name: ${CEO.name}</p><p>Title: ${CEO.office}</p><p>Date signed: __________________________________</p></div>` +
FOUNDERS.map(f => personSig(f.name, 'Class A Member')).join('') +
`<p class="note">The Class B Member, Brock Smith, is admitted under Section 3.7(b) and joins this Agreement through the Talent Amendment. He does not sign this page.</p></div>`;

const body = recitals + art1 + art2 + art3 + art4 + art5 + art6 + art7 + art8 + art9 + art10 + art11 + art12 + art13 + art14 + art15 + art16 + schedA + schedB + schedC + schedD + schedE + scheduleF() + sigPage;

module.exports = function () {
  return H.doc(1, 'LIMITED LIABILITY COMPANY AGREEMENT', body, { h1: H.CO_UP + ' LIMITED LIABILITY COMPANY AGREEMENT' });
};
module.exports.R = R;
